import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.D1JEzK2q.js";const k=JSON.parse('{"title":"Orchestration and tasks","description":"","frontmatter":{},"headers":[],"relativePath":"preview/orchestration.md","filePath":"preview/orchestration.md"}'),n={name:"preview/orchestration.md"};function o(r,e,l,c,d,h){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="orchestration-and-tasks" tabindex="-1">Orchestration and tasks <a class="header-anchor" href="#orchestration-and-tasks" aria-label="Permalink to &quot;Orchestration and tasks&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Unreleased · PR #465</p><p>This page documents the implementation under review in <a href="https://github.com/0xMaxMa/claude-gateway/pull/465" target="_blank" rel="noreferrer">PR #465</a>. It is <strong>not shipped on main</strong>. Preview configuration, commands, and behavior may change before merge. Use a separate evaluation environment and keep gateway and MCP code on the same revision.</p></div><h2 id="what-changes" tabindex="-1">What changes <a class="header-anchor" href="#what-changes" aria-label="Permalink to &quot;What changes&quot;">​</a></h2><p>A managed conversation agent handles the conversation and delegates substantial work to workers. Work has a persistent task record, so you can inspect progress, results, and cancellation independently of a reply.</p><p>The preview uses one boolean <code>gateway.orchestration</code> switch for all agents and connected channels. Per-agent <code>orchestration</code> contains conversation/task tuning. Omitted configuration uses legacy mode. Enabling orchestration sets and saves <code>gateway.headless: true</code>; interactive PTY mode is unsupported. The current process supervisor requires Linux; other platforms reject orchestration with <code>UNSUPPORTED_PROCESS_SUPERVISOR</code>.</p><p>In an evaluation configuration, retain all existing required fields and set <code>gateway.orchestration</code> to <code>true</code>. Check the <a href="https://github.com/0xMaxMa/claude-gateway/pull/465/files" target="_blank" rel="noreferrer">PR files</a> for the current template before tuning worker limits. Do not copy preview fields into a main installation expecting them to activate tasks.</p><h2 id="conversation-intake" tabindex="-1">Conversation intake <a class="header-anchor" href="#conversation-intake" aria-label="Permalink to &quot;Conversation intake&quot;">​</a></h2><p>The optional per-agent <code>orchestration.conversation.semanticIntake: true</code> prepares incomplete material while waiting for a complete instruction. <code>intakeWaitMs</code> defaults to 2000 ms after the latest received material. More material restarts the interval; a complete instruction proceeds without waiting another interval. Model processing can take longer, and recording/upload-in-progress signals are not part of this timer.</p><p>Executable work receives a contextual acknowledgement before task creation. Amendments update the relevant task. Greetings and directly answerable conversation use one normal answer without a separate task acknowledgement.</p><h2 id="inspect-actual-work" tabindex="-1">Inspect actual work <a class="header-anchor" href="#inspect-actual-work" aria-label="Permalink to &quot;Inspect actual work&quot;">​</a></h2><p>After asking an agent to perform a bounded task, inspect it from the same authorized conversation. In supported private chats, <code>/tasks</code> opens task controls. Preview CLI equivalents are:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tasks</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assistant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SESSION_ID</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tasks</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TASK_ID</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assistant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SESSION_ID</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tasks</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> watch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TASK_ID</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assistant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SESSION_ID</span></span></code></pre></div><p>Replace the IDs with real identifiers from your evaluation session. The principal must belong to the session. <code>tasks list --all</code> includes finished work; pagination uses zero-based <code>--page</code> and <code>--page-size</code> from 1 to 100 (default 10). Ctrl+C stops watching only.</p><p>Confirm success from the retained result and relevant files or checks. CPU/I/O movement is evidence of process activity, not proof of useful progress or passing tests. A tool marked <code>returned</code> only means a result arrived.</p><h2 id="cancel-and-reconcile" tabindex="-1">Cancel and reconcile <a class="header-anchor" href="#cancel-and-reconcile" aria-label="Permalink to &quot;Cancel and reconcile&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tasks</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cancel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TASK_ID</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assistant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SESSION_ID</span></span></code></pre></div><p>Cancellation enters <code>cancel_requested</code>; it becomes <code>cancelled</code> after process termination is confirmed. <code>needs_reconciliation</code> with <code>CLEANUP_UNCONFIRMED</code> means cleanup is not proven and may need <strong>Retry cleanup</strong>. Stopping a host Docker client does not prove its container stopped.</p><p>Cancellation preserves files and prior side effects. Before retrying interrupted work, inspect current files, Git state, and test results. A stale progress message is not proof that later edits disappeared.</p><h2 id="understand-time-limits" tabindex="-1">Understand time limits <a class="header-anchor" href="#understand-time-limits" aria-label="Permalink to &quot;Understand time limits&quot;">​</a></h2><p>The preview&#39;s <code>tasks.idleTimeoutMs</code> defaults to 300000 and marks quiet workers for inspection. It does not terminate them for silence alone. <code>tasks.maxDurationMs: 0</code> means no total deadline; a positive value is an explicit hard deadline. Startup and first-response budgets remain bounded.</p><p><code>ORCHESTRATION_DISABLED</code> indicates legacy mode. <code>PROFILE_INVENTORY_MISMATCH</code> indicates a subprocess exposed tools outside its profile: restore a consistent gateway/MCP revision and retain the inventory check.</p><p>The preview covers text orchestration across Telegram, Discord, LINE, Slack, WhatsApp, WeChat, and API conversations. WeChat staged attachments are unsupported. Voice channel support is narrower; see <a href="./voice.html">voice</a>.</p>`,22)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
